{ inputs, lib }:
let
  endpoints = import ./endpoints.nix { inherit lib; };
  helpers = import ./helpers.nix { inherit lib; };
  people = import ./people.nix { inherit lib; };
in
{
  assembly = import ./assembly.nix {
    inherit helpers inputs lib;
  };

  inherit endpoints people;

