{ helpers, inputs, lib }:
let
  unstableOverlay = final: _prev: {
    unstable = import inputs.nixpkgs-unstable {
      inherit (final.stdenv.hostPlatform) system;
      config.allowUnfree = true;
    };
  };

  mkHomePkgs = { overlay, system }:
    import inputs.nixpkgs {
      inherit system;
      config.allowUnfree = true;
      overlays = [
        overlay
        unstableOverlay
      ];
    };

  resolveNixosModule = { flake, name }:
    flake.nixosModules.${name}
    or (throw "Host composition references missing nixos module '${name}'.");

  resolveHomeModule = { flake, name }:
    flake.homeModules.${name}
    or (throw "Home composition references missing home module '${name}'.");
in
rec {
  inherit resolveHomeModule resolveNixosModule;

  mkHost =
    {
      flake,
      genericSiteModule,
      hostName,
      host,
      ...
    }:
    inputs.nixpkgs.lib.nixosSystem {
      inherit (host) system;
      modules =
        [
          genericSiteModule
          {
            _module.args.hostInventory = host;
            _module.args.hostName = hostName;
          }
        ]
        ++ (host.hardwareModules or [ ])
        ++ builtins.map
          (name: resolveNixosModule {
            inherit flake name;
          })
          (helpers.requestedHostModuleNames host);
    };

  mkHome =
    {
      flake,
      genericSiteModule,
      overlay,
      personName,
      person,
    }:
    inputs.home-manager.lib.homeManagerConfiguration {
      pkgs = mkHomePkgs {
        inherit overlay;
        system = person.system;
      };
      modules = [
        genericSiteModule
        (resolveHomeModule {
          inherit flake;
          name = person.homeModule or personName;
        })
      ];
    };

  mkNixosConfigurations =
    {
      flake,
      inventory,
      genericSiteModule,
    }:
    builtins.mapAttrs
      (hostName: host:
        mkHost {
          inherit flake genericSiteModule host hostName;
        })
      (helpers.exportedHosts inventory);

  mkHomeConfigurations =
    {
      flake,
      inventory,
      genericSiteModule,
      overlay,
    }:
    builtins.mapAttrs
      (personName: person:
        mkHome {
          inherit flake genericSiteModule overlay person personName;
        })
      inventory.people;
}

{ endpoints, helpers, lib }:
let
  formatFailures = failures:
    "Dendritic inventory validation failed:\n"
    + lib.concatMapStringsSep "\n" (entry: "- ${entry.message}") failures;

  buildInventoryValidations =
    {
      inventory,
      ...
    }:
    let
      availablePeople = builtins.attrNames inventory.people;
      claimedPorts =
        builtins.map (endpoints.portOf 0) (builtins.attrValues (inventory.ports or { }))
        ++ builtins.map (endpoints.portOf 0) (builtins.attrValues (inventory.reservedPorts or { }));
    in
    [
      {
        assertion = builtins.length claimedPorts == builtins.length (lib.unique claimedPorts);
        message = "Duplicate port found in inventory.ports or inventory.reservedPorts.";
      }
    ]
    ++ lib.concatLists (
      lib.mapAttrsToList
        (hostName: host:
          let
            missingUsers = helpers.missingFrom availablePeople (host.users or [ ]);
            tapeLibraryManager = lib.attrByPath [ "tapeLibrary" "ltfsManager" ] null host;
            allowedTapeLibraryManagers = [
              "fossilsafe"
              "yatm"
            ];
          in
          [
            {
              assertion = missingUsers == [ ];
              message = lib.concatStringsSep " " (
                [
                  "Inventory host '${hostName}' has unresolved references."
                ]
                ++ lib.optionals (missingUsers != [ ]) [
                  "Unknown users: ${helpers.formatNames missingUsers}."
                ]
              );
            }
            {
              assertion =
                tapeLibraryManager == null
                || builtins.elem tapeLibraryManager allowedTapeLibraryManagers;
              message = lib.concatStringsSep " " (
                [
                  "Inventory host '${hostName}' has an invalid tape-library LTFS manager."
                ]
                ++ lib.optionals (tapeLibraryManager != null) [
                  "Expected one of ${helpers.formatNames allowedTapeLibraryManagers}, got '${tapeLibraryManager}'."
                ]
              );
            }
          ])
        inventory.hosts
    )
    ++ lib.mapAttrsToList
      (personName: person:
        let
          missingFields =
            builtins.filter
              (field: !(lib.hasAttrByPath field person))
              [
                [ "home" "username" ]
                [ "home" "directory" ]
                [ "home" "stateVersion" ]
                [ "nixos" "extraGroups" ]
              ];

          formatPath = path: lib.concatStringsSep "." path;
        in
        {
          assertion = missingFields == [ ];
          message = lib.concatStringsSep " " (
            [
              "Inventory person '${personName}' is missing required fields."
            ]
            ++ lib.optionals (missingFields != [ ]) [
              "Missing: ${helpers.formatNames (builtins.map formatPath missingFields)}."
            ]
          );
        })
      inventory.people;

  assertInventory = args:
    let
      failures = builtins.filter (entry: !entry.assertion) (buildInventoryValidations args);
    in
    if failures == [ ] then
      null
    else
      throw (formatFailures failures);
in
{
  inherit assertInventory buildInventoryValidations;
}

