{ inputs, ... }:
{
  flake.nixosModules."tape-library" =
    { lib, pkgs, site, hostInventory, ... }:
    let
      dendriticLib = import ../../../lib {
        inherit inputs lib;
      };
      yamlFormat = pkgs.formats.yaml { };
      fossilsafeFeatureModule = inputs.fossilsafe-feature.nixosModules.fossilsafe;
      fossilsafePackage = inputs.fossilsafe-feature.packages.${pkgs.system}.fossilsafe;
      tapeLibraryPackages = pkgs.callPackage ./tape-library/_packages/tape-library-packages.nix {
        inherit lib;
        ports = site.ports or { };
      };
      fossilsafeEndpoint = dendriticLib.endpoints.normalizeEndpoint 5001 (site.ports.tapeLibraryFossilsafe or { });
      yatmEndpoint = dendriticLib.endpoints.normalizeEndpoint 8081 (site.ports.tapeLibraryYatm or { });
      yatmDebugEndpoint = dendriticLib.endpoints.normalizeEndpoint 8082 (site.ports.tapeLibraryYatmDebug or { });
      fossilsafeInventoryConfig = lib.attrByPath [ "tapeLibrary" "fossilsafe" ] { } hostInventory;
      yatmInventoryConfig = lib.attrByPath [ "tapeLibrary" "yatm" ] { } hostInventory;
      selectedLtfsManager = lib.attrByPath [ "tapeLibrary" "ltfsManager" ] "fossilsafe" hostInventory;
      inherit (tapeLibraryPackages)
        changerDefault
        ltfsDefault
        ltfsOpen
        mtWithDefaults
        mtxWithDefaults
        stfs
        tapeDefault
        yatm
        ;
      selectedLtfsManagerPackage =
        {
          fossilsafe = fossilsafePackage;
          yatm = yatm;
        }
        .${selectedLtfsManager};
      yatmStateDir = lib.attrByPath [ "stateDir" ] "/var/lib/yatm" yatmInventoryConfig;
      yatmSettings = lib.recursiveUpdate
        {
          database = {
            dialect = "sqlite";
            dsn = "${yatmStateDir}/tapes.db";
          };
          debug_listen = "${yatmDebugEndpoint.bind}:${toString yatmDebugEndpoint.port}";
          domain = yatmEndpoint.url;
          listen = "${yatmEndpoint.bind}:${toString yatmEndpoint.port}";
          paths = {
            source = "/";
            target = "/";
            work = "${yatmStateDir}/work";
          };
          scripts = {
            encrypt = "${yatm}/share/yatm/scripts/encrypt";
            mkfs = "${yatm}/share/yatm/scripts/mkfs";
            mount = "${yatm}/share/yatm/scripts/mount";
            read_info = "${yatm}/share/yatm/scripts/readinfo";
            umount = "${yatm}/share/yatm/scripts/umount";
          };
          tape_devices = [ ];
        }
        (lib.attrByPath [ "settings" ] { } yatmInventoryConfig);
      yatmConfigFile = yamlFormat.generate "yatm-config.yaml" yatmSettings;
    in
    {
      imports = [ fossilsafeFeatureModule ];

      boot.kernelModules = [
        "sg"
        "st"
      ];

      services.fossilsafe = lib.mkIf (selectedLtfsManager == "fossilsafe") {
        bootstrap = lib.attrByPath [ "bootstrap" ] { } fossilsafeInventoryConfig;
        enable = true;
        openFirewall = lib.attrByPath [ "openFirewall" ] false fossilsafeInventoryConfig;
        package = fossilsafePackage;
        requireApiKey = lib.attrByPath [ "requireApiKey" ] false fossilsafeInventoryConfig;
        settings = lib.recursiveUpdate
          {
            allowed_origins = builtins.map
              (host: "http://${host}:${toString fossilsafeEndpoint.port}")
              fossilsafeEndpoint.hosts;
            backend_bind = fossilsafeEndpoint.bind;
            backend_port = fossilsafeEndpoint.port;
          }
          (lib.attrByPath [ "settings" ] { } fossilsafeInventoryConfig);
        stateDir = lib.attrByPath [ "stateDir" ] "/var/lib/fossilsafe" fossilsafeInventoryConfig;
      };

      environment.etc."yatm/config.yaml".source = yatmConfigFile;

      environment.sessionVariables = lib.mkIf (selectedLtfsManager == "yatm") {
        YATM_CAPTURED_INDICES_DIR = "${yatmStateDir}/captured_indices";
        YATM_CONFIG = "/etc/yatm/config.yaml";
        YATM_STATE_DIR = yatmStateDir;
      };

      environment.systemPackages = with pkgs; [
        # Bacula's CLI tools are useful for diagnostics and catalog-style tape work.
        bacula
        # Prints the resolved changer path used by the wrapped `mtx` command.
        changerDefault
        # GNU tar is the main archive tool used for direct tape reads and writes.
        gnutar
        # Shows the drive, changer, and matching generic SCSI nodes in one view.
        lsscsi
        # Prints the generic SCSI path LTFS should use for this drive.
        ltfsDefault
        # Upstream LTFS implementation that recognizes the IBM HH5 drive.
        ltfsOpen
        # Extra SCSI inspection utilities such as `sg_inq` and `sg_logs`.
        sg3_utils
        # STFS provides tar-style workflows for older non-LTFS tapes such as LTO-4.
        stfs
        # Prints the resolved non-rewinding tape path used by the wrapped `mt` command.
        tapeDefault
        # Host inventory selects exactly one LTFS manager to avoid changer contention.
        selectedLtfsManagerPackage
        # `mt` falls back to the default non-rewinding tape path when no device flag is given.
        mtWithDefaults
        # `mtx` falls back to the default changer path when no `-f` is given.
        mtxWithDefaults
      ];
    };
}

