{
  flake.nixosModules."host-desktoptoodle" =
    { config, lib, ... }:
    {
      imports = [ ashDesktopModule ];

      networking.hostName = "desktoptoodle";

      boot.loader.grub.enable = lib.mkForce false;
      boot.loader.systemd-boot.enable = true;
      boot.loader.systemd-boot.configurationLimit = 30;
      boot.loader.efi.canTouchEfiVariables = true;
      boot.tmp.useTmpfs = false;
      boot.blacklistedKernelModules = [ "nouveau" ];

      systemd.services.NetworkManager-wait-online.enable = lib.mkForce false;

      services.xserver.videoDrivers = [ "nvidia" ];

      hardware.nvidia = {
        modesetting.enable = true;
        nvidiaSettings = true;
        open = false;
        package = config.boot.kernelPackages.nvidiaPackages.stable;
      };

      users.users.ash.extraGroups = [
        "home-share"
        "tape"
      ];

      systemd.tmpfiles.rules = [
        "L+ /home/ash/games - - - - /srv/games"
      ];
    };
}

{ config, ... }:
{
  flake.nixosModules."host-dev-machine" = {
    imports = [ config.flake.nixosModules."host-dev-machine-game-downloader-staging" ];

    networking.hostName = "dev-machine";
    boot.loader.grub.device = "/dev/sda";

    users.users.ash.uid = 1000;
    users.users.ash.linger = true;
    users.users.ash.extraGroups = [ "home-share" ];
    users.users.madeline.extraGroups = [ "home-share" ];

    systemd.tmpfiles.rules = [
      "z /home/ash 2750 ash home-share - -"
      "z /home/madeline 2750 madeline home-share - -"
      "L+ /home/ash/games - - - - /srv/games"
      "L+ /home/madeline/flake - - - - /home/ash/flake"
      "L+ /home/madeline/games - - - - /srv/games"
    ];
  };
}

