{ lib, pkgs, ports ? { } }:

let
  normalizeEndpoint =
    defaultPort: value:
    if builtins.isAttrs value then
      value // {
        port = value.port or defaultPort;
      }
    else if builtins.isInt value then
      { port = value; }
    else
      { port = defaultPort; };
  changerDefault = pkgs.callPackage ./changer-default.nix { };
  ltfsOpen = pkgs.callPackage ./ltfs-open.nix { };
  tapeDefault = pkgs.callPackage ./tape-default.nix { };
  yatmDebugPort = (normalizeEndpoint 8082 (ports.tapeLibraryYatmDebug or { })).port;
  yatmPort = (normalizeEndpoint 8081 (ports.tapeLibraryYatm or { })).port;
in
rec {
  inherit changerDefault ltfsOpen tapeDefault;

  ltfsDefault = pkgs.callPackage ./ltfs-default.nix {
    inherit lib tapeDefault;
  };

  mtWithDefaults = pkgs.callPackage ./mt-with-defaults.nix {
    inherit lib tapeDefault;
  };

  mtxWithDefaults = pkgs.callPackage ./mtx-with-defaults.nix {
    inherit lib changerDefault;
  };

  stfs = pkgs.callPackage ./stfs.nix { };

  yatm = pkgs.callPackage ./yatm.nix {
    inherit
      lib
      pkgs
      tapeDefault
      ltfsOpen
      mtWithDefaults
      yatmDebugPort
      yatmPort
      ;
  };
}

{ ... }:
{
  flake.nixosModules."host-r640-0" =
    {
      config,
      lib,
      hostInventory,
      pkgs,
      ...
    }:

    let
      zfsPool = hostInventory.zfsPool or null;
      zfsImportService =
        if zfsPool == null then
          null
        else
          "zfs-import-${zfsPool.poolName}.service";
      linkedUsers =
        if zfsPool == null then
          [ ]
        else
          zfsPool.linkedUsers or [ ];
    in
    {
      networking.hostName = "r640-0";

      boot.loader.grub.enable = lib.mkForce false;
      boot.loader.systemd-boot.enable = true;
      boot.loader.systemd-boot.configurationLimit = 10;
      boot.loader.efi.canTouchEfiVariables = true;

      boot.supportedFilesystems = lib.mkIf (zfsPool != null) [ "zfs" ];
      boot.zfs.extraPools = lib.mkIf (zfsPool != null) [ zfsPool.poolName ];
      networking.hostId = lib.mkIf (hostInventory ? hostId) hostInventory.hostId;

      users.users.ash.uid = 1000;
      users.users.ash.linger = true;
      users.users.ash.extraGroups = [ "home-share" ];
      users.users.madeline.extraGroups = [ "home-share" ];
      home-manager.users.ash = {
        programs.git.settings.user = {
          email = "phsilbert@gmail.com";
          name = "ash-r640-0";
        };
      };

      systemd.tmpfiles.rules = [
        "z /home/ash 2750 ash home-share - -"
        "z /home/madeline 2750 madeline home-share - -"
        "L+ /home/ash/games - - - - /srv/games"
        "L+ /home/madeline/flake - - - - /home/ash/flake"
        "L+ /home/madeline/games - - - - /srv/games"
      ];

      systemd.services."zfs-import-${zfsPool.poolName}" = lib.mkIf (zfsPool != null) {
        serviceConfig.ExecCondition = "${pkgs.kmod}/bin/modinfo zfs";
      };

      systemd.services.zfs-home-links = lib.mkIf (zfsPool != null) {
        description = "Link top-level ${zfsPool.poolName} directories into user homes";
        wantedBy = [ "multi-user.target" ];
        after = [
          "local-fs.target"
          zfsImportService
          "zfs-mount.service"
          "systemd-tmpfiles-setup.service"
        ];
        requires = [ zfsImportService ];
        wants = [
          "zfs-mount.service"
        ];
        serviceConfig = {
          Type = "oneshot";
        };
        script =
          let
            users = lib.concatStringsSep " " linkedUsers;
          in
          ''
            set -eu

            pool_name=${lib.escapeShellArg zfsPool.poolName}
            pool_root=${lib.escapeShellArg zfsPool.rootMountPoint}
            users="${users}"

            if ! ${config.boot.zfs.package}/sbin/zpool list -H "$pool_name" >/dev/null 2>&1; then
              echo "zfs-home-links: pool $pool_name is not imported yet, skipping"
              exit 0
            fi

            ${pkgs.coreutils}/bin/mkdir -p "$pool_root"

            if ! ${config.boot.zfs.package}/sbin/zfs mount -a; then
              echo "zfs-home-links: zfs mount -a reported a problem, continuing"
            fi

            if [ ! -d "$pool_root" ]; then
              echo "zfs-home-links: pool root $pool_root is not mounted yet, skipping"
              exit 0
            fi

            for entry in "$pool_root"/*; do
              [ -d "$entry" ] || continue

              name="$(basename "$entry")"

              for user in $users; do
                home_dir="/home/$user"
                destination="$home_dir/$name"

                [ -d "$home_dir" ] || continue

                if [ -L "$destination" ]; then
                  target="$(${pkgs.coreutils}/bin/readlink "$destination")"
                  if [ "$target" = "$entry" ]; then
                    continue
                  fi
                  ${pkgs.coreutils}/bin/ln -sfn "$entry" "$destination"
                  continue
                fi

                if [ -e "$destination" ]; then
                  echo "zfs-home-links: leaving existing path in place: $destination"
                  continue
                fi

                ${pkgs.coreutils}/bin/ln -s "$entry" "$destination"
              done
            done
          '';
      };
    };
}

