      builtins.head driveDevices;
  changerDevice = tapeFacts.changer or null;
  tapeOrg = lib.attrByPath [ "org" "storage" "tape" ] { } hostInventory;
  fossilsafeOrg = tapeOrg.fossilsafe or { };
