+      "base"
+    else if name == "game-library" then
+      "media/game-library"
+    else if name == "desktop-gnome" then
+      "desktop/gnome"
+    else if name == "desktop-cinnamon" then
+      "desktop/cinnamon"
+    else if name == "tape-library" then
+      "storage/tape"
