{ lib }:
let
  directoryNames = root:
    builtins.attrNames (lib.filterAttrs (_: type: type == "directory") (builtins.readDir root));

  requirePath = path: message:
    if builtins.pathExists path then
      path
    else
      throw message;

  mkPassiveEntry = { key, dir, fileName, metaRequired ? false }:
    let
      entryPath = requirePath (dir + "/${fileName}") "Missing registry entrypoint '${toString (dir + "/${fileName}")}'.";
      metaPath = dir + "/meta.nix";
    in
    {
      inherit key;
      module = import entryPath;
      path = dir;
    }
    // lib.optionalAttrs metaRequired {
      meta = import (requirePath metaPath "Missing metadata '${toString metaPath}'.");
    };
in
{
  mkDendriteRegistry = root:
    let
      topLevel = directoryNames root;

      topEntries =
        builtins.listToAttrs (
          builtins.map
            (name: {
              name = name;
              value = mkPassiveEntry {
                key = name;
                dir = root + "/${name}";
                fileName = "${name}.nix";
                metaRequired = true;
              };
            })
            topLevel
        );

      childEntries =
        builtins.listToAttrs (
          lib.concatMap
            (parent:
              let
                childRoot = root + "/${parent}/dendrites";
              in
              if builtins.pathExists childRoot then
                builtins.map
                  (child: {
                    name = "${parent}/${child}";
                    value = mkPassiveEntry {
                      key = "${parent}/${child}";
                      dir = childRoot + "/${child}";
                      fileName = "${child}.nix";
                      metaRequired = true;
                    };
                  })
                  (directoryNames childRoot)
              else
                [ ])
            topLevel
        );
    in
    topEntries // childEntries;

  mkFruitRegistry = root:
    builtins.listToAttrs (
      builtins.map
        (name: {
          name = name;
          value = mkPassiveEntry {
            key = name;
            dir = root + "/${name}";
            fileName = "${name}.nix";
            metaRequired = true;
          };
        })
        (directoryNames root)
    );

  mkHomeRegistry = root:
    let
      sharedRoot = root + "/shared";
      sharedEntries =
        if builtins.pathExists sharedRoot then
          builtins.map
            (name: {
              name = "shared/${name}";
              value = mkPassiveEntry {
                key = "shared/${name}";
                dir = sharedRoot + "/${name}";
                fileName = "${name}.nix";
              };
            })
            (directoryNames sharedRoot)
        else
          [ ];

      userEntries =
        builtins.map
          (name: {
